import java.io.*;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

        int n = readInt(in);
        int[] xs = new int[n];
        int[] ys = new int[n];
        for (int i = 0; i < n; i++) {
            xs[i] = readInt(in);
            ys[i] = readInt(in);
        }

        // Directed tent->tent edges packed as (lenSq << 22) | (u << 11) | v
        // lenSq <= 8*10^8 < 2^30 ; u,v < 2048
        int m = n * (n - 1);
        long[] edges = new long[m];
        int idx = 0;
        for (int u = 0; u < n; u++) {
            long xu = xs[u], yu = ys[u];
            for (int v = 0; v < n; v++) {
                if (u == v) continue;
                long dx = xu - xs[v], dy = yu - ys[v];
                long L = dx * dx + dy * dy;
                edges[idx++] = (L << 22) | (u << 11) | v;
            }
        }

        // squared distance from palace (0,0) to tent i
        long[] d0 = new long[n];
        for (int i = 0; i < n; i++) d0[i] = (long) xs[i] * xs[i] + (long) ys[i] * ys[i];

        Arrays.sort(edges);

        // bestIn[v] = max candies of a route ending at v whose last leg length is
        // greater than the length of the group currently being processed
        int[] bestIn = new int[n];
        int[] stamp = new int[n];
        int[] gbest = new int[n];
        int[] touched = new int[n];
        int gid = 0;
        int ans = 1; // visiting a single tent is always possible

        int i = m - 1;
        while (i >= 0) {
            long L = edges[i] >>> 22;
            int hi = i;
            while (i >= 0 && (edges[i] >>> 22) == L) i--;
            int lo = i + 1;
            gid++;
            int cnt = 0;
            for (int j = lo; j <= hi; j++) {
                long code = edges[j];
                int u = (int) ((code >>> 11) & 2047);
                int v = (int) (code & 2047);
                int f = 0;
                if (d0[u] > L) f = 2;              // palace -> u -> v
                if (bestIn[u] > 0) {               // ... -> w -> u -> v
                    int c = bestIn[u] + 1;
                    if (c > f) f = c;
                }
                if (f == 0) continue;              // edge unreachable
                if (f > ans) ans = f;
                if (stamp[v] != gid) {
                    stamp[v] = gid;
                    gbest[v] = f;
                    touched[cnt++] = v;
                } else if (f > gbest[v]) {
                    gbest[v] = f;
                }
            }
            // deferred updates: equal-length edges cannot be consecutive in a route
            for (int t = 0; t < cnt; t++) {
                int v = touched[t];
                if (gbest[v] > bestIn[v]) bestIn[v] = gbest[v];
            }
        }

        System.out.println(ans);
    }

    private static int readInt(DataInputStream in) throws IOException {
        int ret = 0, b;
        boolean neg = false;
        do {
            b = in.read();
        } while (b != '-' && (b < '0' || b > '9'));
        if (b == '-') {
            neg = true;
            b = in.read();
        }
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return neg ? -ret : ret;
    }
}
